import { plainDate, plainDateToString, type PlainDate } from '@absoluteui/core';
import { DateInput, type DateInputChangeDetail } from '@absoluteui/components/date-input';

const host = document.createElement('div');
document.body.append(host);
DateInput.create(host, { label: 'Due date', name: 'due', min: plainDate(2026, 1, 1), required: true });
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<DateInputChangeDetail>).detail;
  if (value?.kind === 'PlainDate') {
    const due: PlainDate = value;
    document.title = plainDateToString(due);
  }
});

import { configureAbsoluteUI, instantToString } from '@absoluteui/core';
import { DateInput, type DateInputChangeDetail } from '@absoluteui/components/date-input';

configureAbsoluteUI({ common: { timezone: 'Asia/Kolkata' }, components: { dateInput: { disambiguation: 'reject' } } });
const host = document.createElement('div');
document.body.append(host);
DateInput.create(host, { label: 'Meeting time', granularity: 'minute' });
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<DateInputChangeDetail>).detail;
  if (value?.kind === 'Instant') document.title = instantToString(value);
});
